"2864 :   static boolean evaluatesToLocalValue(Node value, Predicate<Node> locals) {
2865 :     switch (value.getType()) {
2866 :       case Token.ASSIGN:
2867 :         // A result that is aliased by a non-local name, is the effectively the
2868 :         // same as returning a non-local name, but this doesn't matter if the
2869 :         // value is immutable.
2870 :         return NodeUtil.isImmutableValue(value.getLastChild())
2871 :             || (locals.apply(value)
2872 :                 && evaluatesToLocalValue(value.getLastChild(), locals));
2873 :       case Token.COMMA:
2874 :         return evaluatesToLocalValue(value.getLastChild(), locals);
2875 :       case Token.AND:
2876 :       case Token.OR:
2877 :         return evaluatesToLocalValue(value.getFirstChild(), locals)
2878 :            && evaluatesToLocalValue(value.getLastChild(), locals);
2879 :       case Token.HOOK:
2880 :         return evaluatesToLocalValue(value.getFirstChild().getNext(), locals)
2881 :            && evaluatesToLocalValue(value.getLastChild(), locals);
2882 :       case Token.INC:
2883 :       case Token.DEC:
2884 :         if (value.getBooleanProp(Node.INCRDECR_PROP)) {
2885 :           return evaluatesToLocalValue(value.getFirstChild(), locals);
2886 :         } else {
2887 :           return true;
2888 :         }
2889 :       case Token.THIS:
2890 :         return locals.apply(value);
2891 :       case Token.NAME:
2892 :         return isImmutableValue(value) || locals.apply(value);
2893 :       case Token.GETELEM:
2894 :       case Token.GETPROP:
2895 :         // There is no information about the locality of object properties.
2896 :         return locals.apply(value);
2897 :       case Token.CALL:
2898 :         return callHasLocalResult(value)
2899 :             || isToStringMethodCall(value)
2900 :             || locals.apply(value);
2901 :       case Token.NEW:
2902 :         return newHasLocalResult(value)
2903 :                || locals.apply(value);
2904 :       case Token.FUNCTION:
2905 :       case Token.REGEXP:
2906 :       case Token.ARRAYLIT:
2907 :       case Token.OBJECTLIT:
2908 :         // Literals objects with non-literal children are allowed.
2909 :         return true;
2910 :       case Token.IN:
2911 :         // TODO(johnlenz): should IN operator be included in #isSimpleOperator?
2912 :         return true;
2913 :       default:
2914 :         // Other op force a local value:
2915 :         //  x = '' + g (x is now an local string)
2916 :         //  x -= g (x is now an local number)
2917 :         if (isAssignmentOp(value)
2918 :             || isSimpleOperator(value)
2919 :             || isImmutableValue(value)) {
2920 :           return true;
2921 :         }
2922 : 
2923 :         throw new IllegalStateException(
2924 :             "Unexpected expression node" + value +
2925 :             "\n parent:" + value.getParent());
2926 :     }
2927 :   }"

"1157 :   static boolean valueCheck(Node n, Predicate<Node> p) {
1158 :     switch (n.getType()) {
1159 :       case Token.ASSIGN:
1160 :       case Token.COMMA:
1161 :         return valueCheck(n.getLastChild(), p);
1162 :       case Token.AND:
1163 :       case Token.OR:
1164 :         return valueCheck(n.getFirstChild(), p)
1165 :             && valueCheck(n.getLastChild(), p);
1166 :       case Token.HOOK:
1167 :         return valueCheck(n.getFirstChild().getNext(), p)
1168 :             && valueCheck(n.getLastChild(), p);
1169 :       default:
1170 :         return p.apply(n);
1171 :     }
1172 :   }"

"459 :   static boolean isImmutableValue(Node n) {
460 :     switch (n.getType()) {
461 :       case Token.STRING:
462 :       case Token.NUMBER:
463 :       case Token.NULL:
464 :       case Token.TRUE:
465 :       case Token.FALSE:
466 :         return true;
467 :       case Token.NOT:
468 :         return isImmutableValue(n.getFirstChild());
469 :       case Token.VOID:
470 :       case Token.NEG:
471 :         return isImmutableValue(n.getFirstChild());
472 :       case Token.NAME:
473 :         String name = n.getString();
474 :         // We assume here that programs don't change the value of the keyword
475 :         // undefined to something other than the value undefined.
476 :         return "undefined".equals(name)
477 :             || "Infinity".equals(name)
478 :             || "NaN".equals(name);
479 :     }
480 : 
481 :     return false;
482 :   }"

